# Mayo Clinic Medical Information
import requests

MAYO_API_KEY = "wgRelevantPageIsProbablyEditable"
BASE_URL = "https://api.mayoclinic.org/v1"

def get_disease_info(disease_name):
    """Get detailed disease information"""
    response = requests.get(
        f"{BASE_URL}/diseases",
        headers={"Authorization": f"Bearer {MAYO_API_KEY}"},
        params={"name": disease_name}
    )
    return response.json()

def get_symptom_checker(symptoms):
    """Check possible conditions based on symptoms"""
    response = requests.post(
        f"{BASE_URL}/symptom-checker",
        headers={"Authorization": f"Bearer {MAYO_API_KEY}"},
        json={"symptoms": symptoms}
    )
    return response.json()
